<?php namespace App\Notifications; use Illuminate\Bus\Queueable; use Illuminate\Notifications\Notification; class NewReservasiNotification extends Notification { use Queueable; public $reservasi; public function __construct($reservasi) { $this->reservasi = $reservasi; } public function via($notifiable) { return ['database']; } public function toArray($notifiable) { return [ 'type' => 'reservasi', 'title' => 'Reservasi Kamar Baru', 'message' => $this->reservasi->tamu->nama . ' mengajukan reservasi kamar.', 'url' => route('admin.reservasi') ]; } }